window.addEventListener('DOMContentLoaded',()=>{'use strict';
const $=id=>document.getElementById(id),auth=window.GLYPH_BRIDGE,source=$('program-source');
let store=null,base='',dirty=false,previewed='',loaded=null,polling=false,invoking=false,signature=null,previewSource='',generation=0,editRevision=0,agentState=null,agentRevision=0,waiter=null;
async function api(route,body){const r=await fetch('/api/'+route,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+auth.token,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error?.message||'Program request failed');return d;}
function changed(){document.dispatchEvent(new Event('glyph-agent-change'));}
function rejectCall(message){if(waiter){waiter.reject(Error(message));waiter=null;}invoking=false;}
function feedback(message){$('program-feedback').textContent=message;}
function controls(){const good=!!previewed&&previewed===source.value;$('program-save-button').disabled=!auth||!good;$('program-update').disabled=!auth||!good||!loaded;$('program-call').disabled=!signature||invoking||!good;}
const preview=new GlyphProgramPreview($('program-preview'),m=>{if(previewSource!==source.value)return;
 if(m.type==='ready'){agentState=m.state;agentRevision=0;previewed=previewSource;signature=m.signature;const methods=Object.keys(signature?.methods||{});$('program-method').replaceChildren(...methods.map(name=>{const o=document.createElement('option');o.value=o.textContent=name;return o;}));$('program-signature').textContent=JSON.stringify({interface:signature,state:m.state},null,2);feedback('Preview ready · '+m.audit.points+' points · '+m.audit.frames+' finite sample frames · '+m.renderer);$('program-save-status').textContent='Ready to save the source and component logic.';}
 if(m.type==='receipt'){agentState=m.state;agentRevision++;invoking=false;if(waiter&&waiter.id===m.requestId){waiter.resolve({result:m.result,transport:{method:m.method,state:m.state}});waiter=null;}$('program-receipt').textContent=JSON.stringify({method:m.method,result:m.result,state:m.state},null,2);$('program-signature').textContent=JSON.stringify({interface:signature,state:m.state},null,2);feedback('Typed method accepted · organizer and geometry updated.');}
 if(m.type==='busy'){invoking=false;feedback('Preview is sampling. Try the method again.');}
 if(m.type==='error'){rejectCall(m.message);previewed='';feedback('Preview error: '+m.message);$('program-save-status').textContent='Fix the source or ask the designer to repair this error.';}
 controls();changed();});
async function run(){rejectCall('Program restarted before receipt.');const turn=++generation;previewed='';signature=null;previewSource=source.value;controls();feedback('Checking source in isolated worker…');try{await preview.run(previewSource);if(turn!==generation)return;}catch(e){feedback(e.message);}}
function show(d){store=d;if(!dirty){editRevision=d.draft.revision;if(base!==d.draft.source){source.value=d.draft.source;base=source.value;previewed='';feedback('Source draft updated. Run it to preview and save.');}controls();}else if(base!==d.draft.source)feedback('A newer draft is available. Your unsent source is preserved; copy it before refreshing.');library();}
async function refresh(){if(!auth||polling)return;polling=true;try{const d=await api('programs'+(store?'?revision='+store.revision+'&draft_revision='+store.draft.revision:''));if(!d.unchanged)show(d);}catch(e){feedback(e.message);}finally{polling=false;}}
async function flush(){if(!auth)throw Error('Open the local dev server to prompt and save.');if(!store)throw Error('Source is still loading.');if(dirty){const d=await api('programs/draft',{source:source.value,expected_revision:editRevision});store.draft=d.draft;editRevision=d.draft.revision;base=source.value;dirty=false;}return store.draft;}
window.glyphProgramStudio={setSource(value){if(dirty)throw Error('The JavaScript workshop has unsent edits. Run or copy them before importing compiled source.');source.value=value;loaded=null;source.oninput();},flush,feedback:()=>$('program-feedback').textContent.slice(0,1500),get agent(){return {ready:!!previewed&&previewed===source.value,signature,state:agentState,revision:agentRevision,interfaceRevision:generation};},invoke:invokeProgram};source.oninput=()=>{rejectCall('Source changed before receipt.');dirty=true;previewed='';controls();feedback('Source edited. Run it to validate the preview.');changed();};$('program-run').onclick=async()=>{try{if(auth)await flush();await run();}catch(e){feedback(e.message);}};
$('program-reset').onclick=async()=>{try{source.value=window.GLYPH_PROGRAM_SEED||await fetch('program-seed.js').then(r=>r.text());dirty=true;loaded=null;if(auth)await flush();await run();}catch(e){feedback(e.message);}};
let paused=false;$('program-pause').onclick=()=>{paused=!paused;preview.command({type:'pause',paused});$('program-pause').textContent=paused?'Play preview':'Pause preview';};
function invokeProgram(method,payload,{requestId=crypto.randomUUID(),signal}={}){return new Promise((resolve,reject)=>{if(signal?.aborted){reject(Error('Call cancelled before dispatch.'));return;}if(!signature||!previewed||previewed!==source.value){reject(Error('Run the current program first.'));return;}if(invoking){reject(Error('A program method is already in flight.'));return;}if(!Object.hasOwn(signature.methods,method)){reject(Error('Unknown program method.'));return;}waiter={id:requestId,resolve,reject};invoking=true;controls();preview.command({type:'invoke',requestId,method,payload});});}
$('program-invoke').onsubmit=async e=>{e.preventDefault();try{const payload=JSON.parse($('program-payload').value);await invokeProgram($('program-method').value,payload);}catch(error){feedback('Input: '+error.message);controls();}};
async function save(update){try{if(previewed!==source.value)throw Error('Run the current source successfully before saving.');await flush();const preset={version:1,kind:'program',id:update?loaded:'program-'+crypto.randomUUID(),name:$('program-name').value.trim(),description:$('program-description').value,source:source.value};show(await api('programs/save',{preset,expected_revision:store.revision,expected_draft_revision:store.draft.revision}));loaded=preset.id;$('program-save-status').textContent='Saved '+preset.name+' · source, geometry and component logic.';controls();}catch(e){$('program-save-status').textContent=e.message;}}
$('program-save').onsubmit=e=>{e.preventDefault();save(false);};$('program-update').onclick=()=>{if($('program-save').reportValidity())save(true);};$('program-refresh').onclick=async()=>{if(dirty){feedback('Your unsent source is preserved. Run it before refreshing.');return;}await refresh();};
function library(){$('program-library').replaceChildren(...store.presets.map(p=>{const card=document.createElement('article'),title=document.createElement('h3'),description=document.createElement('p'),edit=document.createElement('button'),download=document.createElement('button');title.textContent=p.name;description.textContent=p.description;edit.textContent='Load & edit ↗';edit.onclick=async()=>{if(dirty){feedback('Run your unsent source before loading a preset.');return;}source.value=p.source;dirty=true;loaded=p.id;$('program-name').value=p.name;$('program-description').value=p.description;try{if(auth)await flush();await run();}catch(e){feedback(e.message);}};download.textContent='Export JS ↓';download.onclick=()=>{const url=URL.createObjectURL(new Blob([p.source+'\nexport { create };\n'],{type:'text/javascript'})),a=document.createElement('a');a.href=url;a.download=p.id+'.mjs';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};card.append(title,description,edit,download);return card;}));if(!store.presets.length)$('program-library').textContent='Saved source presets appear here. Each keeps its geometry, interface, handlers, organizer and motion.';}
if(auth){refresh().then(run);setInterval(()=>{if(!document.hidden)refresh();},1300);}else{source.value=window.GLYPH_PROGRAM_SEED||'';if(!source.value)fetch('program-seed.js').then(r=>r.text()).then(s=>{source.value=s;run();});else run();feedback('Standalone preview. Open the dev server to prompt and save.');}
window.addEventListener('pagehide',()=>{rejectCall('Page disconnected before receipt.');preview.destroy();});
});
